fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // sep is guaranteed non-empty per problem statement

    a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                // No splitting, just return string as single-element vec
                vec![s]
            } else if s.is_empty() {
                // empty string returns vec with one empty string
                vec![String::new()]
            } else {
                // Use rsplitn to split at most maxsplit times, from right
                let mut parts: Vec<String> = s
                    .rsplitn((maxsplit as usize) + 1, &sep)
                    .map(|part| part.to_string())
                    .collect();

                // rsplitn returns parts in reverse order; reverse to match original left->right order
                parts.reverse();
                parts
            }
        })
        .collect()
}